<template><div class="native-visual" :class="{'native-readonly':readOnly}"><section class="native-blocks"><div class="native-panel-caption"><span>VISUAL EDITOR</span><KsButton size="small" @click="selected=''">Flow 属性</KsButton></div><div v-if="error" class="native-error">{{error}}</div><template v-if="doc">
<BlockSectionCard v-if="controlled" name="device-steps" title="Tasks" :icon="Console" :count="steps.length" addLabel="添加任务" @add="addingDevice=true"><LeafBlockCard v-for="(step,index) in steps" :key="step.id" :block="{...step,type:step.kind==='python'?'Python Script':step.kind==='bash'?'Shell Script':'Command'}" :path="`inputs.steps[${index}]`" :selected="selected==='step:'+step.id" :focused="selected==='step:'+step.id" :showDelete="!step.implicit" :showOpenSplit="false" :showDuplicate="false" :runnable="false" :draggable="!readOnly&&!step.implicit" @drag-start="dragged='step:'+step.id" @drag-end="dragged=''" @drop="reorderStep(step.id)" @select="selected='step:'+step.id" @delete="removeStep(step.id)"/></BlockSectionCard>
<details v-if="controlled" class="adapter-details"><summary>执行适配信息</summary><p class="native-note">底层编排保留在同一份 YAML 中，设备任务仍通过项目授权、预检和审批。</p><BlockSectionCard v-for="branch in branches.filter(b=>b==='tasks'||doc[b]?.length)" :key="branch" :name="branch" :title="branch==='tasks'?'执行适配':branch" :icon="ViewSequential" :count="doc[branch]?.length||0" addLabel="添加任务" @add="startAdd(branch)"><div v-for="item in visibleTree(doc[branch]||[],branch)" :key="item.task.id" class="native-block-item" :style="{marginLeft:item.depth*15+'px'}"><button v-if="branches.some(key=>item.task[key]?.length)" class="native-child-toggle" @click="expanded.includes(item.task.id)?expanded=expanded.filter(id=>id!==item.task.id):expanded.push(item.task.id)">{{expanded.includes(item.task.id)?'▾':'▸'}} 子任务</button><small v-if="item.parent">{{item.parent}} / {{item.branch}}</small><LeafBlockCard :block="item.task" :path="item.path" :selected="selected===item.task.id" :focused="selected===item.task.id" :showOpenSplit="false" :showDuplicate="false" :runnable="false" :draggable="!readOnly" @drag-start="dragged=item.task.id" @drag-end="dragged=''" @drop="reorder(item.task.id)" @select="selected=item.task.id" @delete="edit(d=>removeTask(d,item.task.id))"/></div></BlockSectionCard></details><template v-else><BlockSectionCard v-for="branch in branches.filter(b=>b==='tasks'||doc[b]?.length)" :key="branch" :name="branch" :title="branch==='tasks'?'Tasks':branch" :icon="ViewSequential" :count="doc[branch]?.length||0" addLabel="添加任务" @add="startAdd(branch)"><div v-for="item in visibleTree(doc[branch]||[],branch)" :key="item.task.id" class="native-block-item" :style="{marginLeft:item.depth*15+'px'}"><button v-if="branches.some(key=>item.task[key]?.length)" class="native-child-toggle" @click="expanded.includes(item.task.id)?expanded=expanded.filter(id=>id!==item.task.id):expanded.push(item.task.id)">{{expanded.includes(item.task.id)?'▾':'▸'}} 子任务</button><small v-if="item.parent">{{item.parent}} / {{item.branch}}</small><LeafBlockCard :block="item.task" :path="item.path" :selected="selected===item.task.id" :focused="selected===item.task.id" :showOpenSplit="false" :showDuplicate="false" :runnable="false" :draggable="!readOnly" @drag-start="dragged=item.task.id" @drag-end="dragged=''" @drop="reorder(item.task.id)" @select="selected=item.task.id" @delete="edit(d=>removeTask(d,item.task.id))"/></div></BlockSectionCard></template></template></section><aside class="native-inspector"><div class="native-panel-caption">PROPERTIES</div><template v-if="step"><h3>{{step.id}}</h3><label>Description<input :value="step.description||''" maxlength="2000" :disabled="readOnly" @change="stepField('description',value($event))"/></label><label>超时（秒）<input type="number" min="0" max="3600" :value="step.timeout_seconds||''" placeholder="继承作业时限" :disabled="readOnly" @change="stepField('timeout_seconds',Number(value($event)))"/></label><label>类型<select :value="step.kind" :disabled="readOnly" @change="stepField('kind',value($event))"><option>bash</option><option>python</option><option>command</option></select></label><label v-if="sourceRef">Script source<code>{{sourceRef.path}} · rev {{sourceRef.revision}}</code><small>{{sourceRef.mode==='namespace'?'Namespace 固定版本引用':'内联快照 · 保留原文件来源'}}</small></label><label>脚本<NativeCodeEditor :source="step.command||''" :readOnly="readOnly||sourceRef?.mode==='namespace'" :path="step.id+(step.kind==='python'?'.py':'.sh')" :language="step.kind==='python'?'python':'shell'" :theme="theme" @change="v=>stepField('command',v)" @save="emit('save')"/></label><div class="native-inspector-actions"><KsButton :disabled="readOnly" @click="emit('files',step.id)">{{sourceRef?'在脚本编辑器中打开':'编辑脚本文件'}}</KsButton><KsButton v-if="sourceRef?.mode==='namespace'" size="small" :disabled="readOnly" @click="edit(d=>setScriptSource(d,step.id,{...sourceRef,mode:'inline'}))">转为内联编辑</KsButton></div><label v-if="!step.implicit">前置步骤<select multiple :value="step.depends_on" :disabled="readOnly" @change="stepField('depends_on',Array.from(($event.target as HTMLSelectElement).selectedOptions,o=>o.value))"><option v-for="other in steps.filter(s=>s.id!==step.id)" :key="other.id">{{other.id}}</option></select></label><label v-if="!step.implicit">输出绑定 JSON<textarea :value="JSON.stringify(step.inputs||{},null,2)" :disabled="readOnly" @change="stepJSON(value($event))"/></label></template>
<template v-else-if="task"><h3>{{task.id}}</h3><code>{{task.type}}</code><label>Description<input :value="task.description||''" :disabled="readOnly" @change="field('description',value($event))"/></label><label v-for="name in ['message','condition','namespace','flowId','timeout'] .filter(k=>k in task||k==='timeout')" :key="name">{{name}}<textarea v-if="name==='message'" :value="task[name]||''" :disabled="readOnly" @change="field(name,value($event))"/><input v-else :value="task[name]||''" :disabled="readOnly" @change="field(name,value($event))"/></label><label v-if="'script' in task">Inline script<NativeCodeEditor :source="task.script||''" :readOnly="readOnly" :path="task.id+(task.type.includes('.python.')?'.py':'.sh')" :language="task.type.includes('.python.')?'python':'shell'" :theme="theme" @change="v=>field('script',v)" @save="emit('save')"/></label><label v-if="'values' in task">Values<textarea :value="typeof task.values==='string'?task.values:JSON.stringify(task.values,null,2)" :disabled="readOnly" @change="valuesField(value($event))"/></label><label>额外重试次数<input type="number" min="0" max="10" :value="Math.max(0,(task.retry?.maxAttempts||1)-1)" :disabled="readOnly||task.type==='io.kestra.plugin.core.http.Request'" @change="retry(Number(value($event)))"/></label><div class="native-inspector-actions"><KsButton :disabled="readOnly" size="small" @click="edit(d=>moveTask(d,task.id,-1))">上移</KsButton><KsButton :disabled="readOnly" size="small" @click="edit(d=>moveTask(d,task.id,1))">下移</KsButton><KsButton :disabled="readOnly" size="small" @click="startAdd('tasks',task.id)">添加子任务</KsButton></div><p class="native-note">未知插件字段保留。完整参数及复杂分支可在 YAML 编辑。</p></template>
<template v-else-if="doc"><h3>{{doc.id||'New Flow'}}</h3><label>Namespace<input :value="doc.namespace" readonly/></label><label>Flow 并发<input type="number" min="1" max="64" :value="doc.concurrency?.limit||1" :disabled="readOnly" @change="edit(d=>d.concurrency={limit:Number(value($event)),behavior:'QUEUE'})"/></label><label v-if="controlled">设备通道<select :value="inputDefault(doc,'transport_policy','agent_preferred')" :disabled="readOnly" @change="edit(d=>setDefault(d,'transport_policy',value($event)))"><option value="agent_preferred">Agent Preferred</option><option value="agent_only">Agent Only</option><option value="ssh_only">SSH Only</option></select></label><label v-for="input in (doc.inputs||[]).filter(i=>!['ticket','targets','steps',...(controlled?['kind','command','transport_policy']:[])].includes(i.id))" :key="input.id">{{input.id}}<input :value="input.type==='SECRET'?'':typeof input.defaults==='object'?JSON.stringify(input.defaults):input.defaults" :placeholder="input.type==='SECRET'?'受控秘密引用':input.type" :disabled="readOnly||input.type==='SECRET'" @change="edit(d=>setDefault(d,input.id,value($event),input.type))"/></label><label>新任务区域<select v-model="addBranch"><option value="tasks">Tasks</option><option value="errors">On error</option><option value="finally">Finally</option></select></label><KsButton :disabled="readOnly" @click="controlled?addingDevice=true:startAdd(addBranch)">添加任务</KsButton></template></aside>
<KsDialog v-model="addingDevice" title="添加设备任务" :teleported="false" :appendToBody="false" width="500px"><div class="native-task-picker"><KsButton v-for="item in deviceCatalog" :key="item.kind" :disabled="readOnly" @click="addStep(item.kind);addingDevice=false"><Console :size="18"/><span>{{item.label}}</span><small>CMDB 设备执行</small></KsButton><p class="native-note">在目标服务器或交换机执行，仍须预检和审批；不会在 Kestra Worker 上执行。</p></div></KsDialog><KsDialog v-model="adding" title="添加任务" :teleported="false" :appendToBody="false" width="500px"><label v-if="addParent&&taskList(doc||{}).find(t=>t.id===addParent)?.type.endsWith('.If')">插入分支<select v-model="addBranch"><option value="then">Then</option><option value="else">Else</option></select></label><div class="native-task-picker"><KsButton v-for="item in catalog" :key="item.type" :disabled="readOnly" @click="addTask(item.type)"><Console :size="18"/><span>{{item.label}}</span><small>{{item.type.split('.').slice(-2).join('.')}}</small></KsButton></div></KsDialog></div></template>
<script setup lang="ts">
import {computed,ref} from 'vue';import YAML from 'yaml';
import BlockSectionCard from '../../vendor/kestra/no-code/BlockSectionCard.vue';import LeafBlockCard from '../../vendor/kestra/no-code/LeafBlockCard.vue';
import KsButton from '../../vendor/kestra/design-system/components/Basic/KsButton/KsButton.vue';import KsDialog from '../../vendor/kestra/design-system/components/Feedback/KsDialog.vue';import Console from 'vue-material-design-icons/Console.vue';import ViewSequential from 'vue-material-design-icons/ViewSequential.vue';
import NativeCodeEditor from './NativeCodeEditor.vue';
import {scriptSources,setScriptSource} from '../flows/script-sources';
import {branches,taskList,locate,removeTask,moveTask,isControlled,inputDefault,setDefault,checkStructure,connectSteps,deliverySteps,type Definition,type Task} from '../flows/definition';
const props=defineProps<{source:string;readOnly:boolean;theme:'dark'|'light';selected:string}>();const emit=defineEmits(['change','save','files','select']);
const selected=computed({get:()=>props.selected,set:value=>emit('select',value)}),error=ref(''),addingDevice=ref(false),adding=ref(false),addBranch=ref('tasks'),addParent=ref(''),dragged=ref(''),expanded=ref<string[]>([]);
const doc=computed<Definition|null>(()=>{try{const d=YAML.parse(props.source);checkStructure(d);return d}catch{return null}}),controlled=computed(()=>!!doc.value&&isControlled(doc.value));
const steps=computed<any[]>(()=>doc.value?deliverySteps(doc.value):[]),step=computed(()=>steps.value.find(s=>'step:'+s.id===selected.value)),sourceRef=computed(()=>step.value&&doc.value?scriptSources(doc.value)[step.value.id]:undefined),task=computed(()=>doc.value?taskList(doc.value).find(t=>t.id===selected.value):null);
const deviceCatalog=[{kind:'bash',label:'Shell Script'},{kind:'python',label:'Python Script'},{kind:'command',label:'Command'}];
const catalog=[['Log','io.kestra.plugin.core.log.Log'],['Parallel','io.kestra.plugin.core.flow.Parallel'],['Condition','io.kestra.plugin.core.flow.If'],['Loop','io.kestra.plugin.core.flow.Loop'],['Subflow','io.kestra.plugin.core.flow.Subflow'],['Output Values','io.kestra.plugin.core.output.OutputValues']].map(([label,type])=>({label,type}));
const value=(event:Event)=>(event.target as HTMLInputElement).value;
function edit(fn:(d:Definition)=>void){if(props.readOnly)return;try{const d=YAML.parse(props.source);fn(d);checkStructure(d);emit('change',YAML.stringify(d));error.value=''}catch(e){error.value=String(e)}}
function tree(tasks:Task[],branch:string,parent='',depth=0):{task:Task;path:string;parent:string;branch:string;depth:number}[]{return tasks.flatMap((task,i)=>[{task,path:`${branch}[${i}]`,parent,branch,depth},...branches.flatMap(b=>tree(task[b]||[],b,task.id,depth+1))])}
function visibleTree(tasks:Task[],branch:string,parent='',depth=0):{task:Task;path:string;parent:string;branch:string;depth:number}[]{return tasks.flatMap((task,i)=>[{task,path:`${branch}[${i}]`,parent,branch,depth},...(expanded.value.includes(task.id)?branches.flatMap(b=>visibleTree(task[b]||[],b,task.id,depth+1)):[])])}
function reorderStep(target:string){const id=dragged.value.replace(/^step:/,'');if(id===target)return;edit(d=>{const all=inputDefault(d,'steps',[]),from=all.findIndex((s:any)=>s.id===id),to=all.findIndex((s:any)=>s.id===target);if(from<0||to<0)return;const [step]=all.splice(from,1);all.splice(to,0,step);const seen=new Set();for(const item of all){if(item.depends_on.some((id:string)=>!seen.has(id)))throw Error('此移动将把任务放在依赖之前；请先调整依赖关系');seen.add(item.id)}setDefault(d,'steps',all,'JSON')});dragged.value=''}
function reorder(target:string){if(!dragged.value||dragged.value===target)return;edit(d=>{const from=locate(d,dragged.value),to=locate(d,target);if(!from||!to||from.list!==to.list)throw Error('只能在同一任务分支内拖动排序');const [item]=from.list.splice(from.index,1);from.list.splice(from.list.findIndex(t=>t.id===target),0,item)});dragged.value=''}
function field(key:string,value:unknown){edit(d=>{const found=locate(d,selected.value);if(found)found.list[found.index][key]=value})}
function retry(extra:number){if(!Number.isInteger(extra)||extra<0||extra>10){error.value='重试次数应为 0–10';return}edit(d=>{const f=locate(d,selected.value);if(!f)return;if(extra)f.list[f.index].retry={type:'constant',maxAttempts:extra+1,interval:'PT1S'};else delete f.list[f.index].retry})}
function valuesField(value:string){try{field('values',task.value?.type.endsWith('.OutputValues')?JSON.parse(value):value)}catch{error.value='Values 必须是 JSON 对象'}}
function stepField(key:string,value:unknown){edit(d=>{if((key==='command'||key==='kind')&&sourceRef.value?.mode==='namespace')setScriptSource(d,step.value.id,{...sourceRef.value,mode:'inline'});if(step.value?.implicit){if(key==='command'||key==='kind')setDefault(d,key,value);else if(key==='description'||key==='timeout_seconds'){const {implicit,...current}=step.value;setDefault(d,'steps',[{...current,[key]:value}],'JSON')}return}const all=inputDefault(d,'steps',[]),item=all.find((s:any)=>'step:'+s.id===selected.value);if(!item)return;if(key==='depends_on'){item.depends_on=[];for(const id of value as string[])connectSteps(all,id,item.id)}else item[key]=value;setDefault(d,'steps',all,'JSON')})}
function stepJSON(value:string){try{stepField('inputs',JSON.parse(value))}catch{error.value='输出绑定必须是 JSON 对象'}}
function removeStep(id:string){edit(d=>{const all=inputDefault(d,'steps',[]);if(all.some((s:any)=>s.depends_on.includes(id)||Object.values(s.inputs||{}).includes(id)))throw Error('先解除引用此步骤的依赖和输出绑定');setDefault(d,'steps',all.filter((s:any)=>s.id!==id),'JSON');setScriptSource(d,id)})}
function addStep(kind='bash'){edit(d=>{const all=inputDefault(d,'steps',[]);if(!all.length&&inputDefault(d,'command','').trim())all.push({id:'command',kind:inputDefault(d,'kind','bash'),command:inputDefault(d,'command'),depends_on:[],inputs:{}});const id='step_'+crypto.randomUUID().slice(0,6);all.push({id,kind,command:'',depends_on:all.length?[all.at(-1).id]:[],inputs:{}});setDefault(d,'steps',all,'JSON');selected.value='step:'+id})}
function startAdd(branch:string,parent=''){if(props.readOnly)return;addBranch.value=parent&&taskList(doc.value||{}).find(t=>t.id===parent)?.type.endsWith('.If')?'then':branch;addParent.value=parent;adding.value=true}
function addTask(type:string){edit(d=>{const id='task_'+crypto.randomUUID().slice(0,6);const item:Task={id,type};if(type.endsWith('.Script'))item.script=type.includes('.python.')?'#!/usr/bin/env python3\n':'#!/usr/bin/env bash\nset -euo pipefail\n';if(type.endsWith('.Log'))item.message='';if(type.endsWith('.Parallel'))item.tasks=[];if(type.endsWith('.If'))Object.assign(item,{condition:'',then:[],else:[]});if(type.endsWith('.Loop'))Object.assign(item,{values:'{{ inputs.items }}',tasks:[],concurrencyLimit:8});if(type.endsWith('.Subflow'))Object.assign(item,{namespace:d.namespace,flowId:''});if(type.endsWith('.OutputValues'))item.values={};const parent=addParent.value?taskList(d).find(t=>t.id===addParent.value):d;if(!parent)throw Error('父任务不存在');if(parent!==d&&!branches.some(b=>Array.isArray(parent[b])))throw Error('该节点不支持子任务，请选择容器任务');const branch=parent===d?addBranch.value:parent.type.endsWith('.If')?(addBranch.value==='else'?'else':'then'):'tasks';parent[branch]||=[];parent[branch].push(item);selected.value=id});adding.value=false}
</script>
<style scoped>
.native-visual{height:100%;display:grid;grid-template-columns:minmax(230px,1fr) 235px;color:var(--ks-text-primary);font-size:12px}.native-blocks{padding:14px;overflow:auto}.native-panel-caption{display:flex;align-items:center;justify-content:space-between;font-size:10px;letter-spacing:.08em;color:var(--ks-text-secondary);margin-bottom:14px}.native-block-item{margin-bottom:8px}.native-block-item small{display:block;font:10px monospace;color:var(--ks-text-secondary);margin-bottom:3px}.native-inspector{padding:16px;border-left:1px solid var(--ks-border-default);overflow:auto;background:var(--ks-bg-surface)}.native-inspector label{display:block;font-size:11px;margin:14px 0;color:var(--ks-text-secondary)}.native-inspector input,.native-inspector select,.native-inspector textarea{display:block;width:100%;box-sizing:border-box;margin-top:6px;border:1px solid var(--ks-border-default);border-radius:4px;padding:8px;background:var(--ks-bg-input);color:var(--ks-text-primary);font:12px var(--ks-font-family-sans)}.native-inspector textarea{min-height:90px}.native-inspector code{font-size:10px;overflow-wrap:anywhere}.native-inspector :deep(.native-code-editor){height:280px;min-height:220px}.native-inspector-actions{display:flex;gap:6px;flex-wrap:wrap}.native-error{padding:10px;color:var(--ks-text-error)}.native-note{color:var(--ks-text-secondary);font-size:11px;line-height:1.6}.native-task-picker{display:grid;gap:8px}.native-task-picker :deep(button){justify-content:flex-start}.native-task-picker small{margin-left:auto;font:10px monospace}.native-readonly :deep(.leaf-block-card-actions),.native-readonly :deep(.block-section-add){display:none}@media(max-width:1250px){.native-visual{grid-template-columns:minmax(220px,1fr)}.native-inspector{border-left:0;border-top:1px solid var(--ks-border-default)}}
.adapter-details{margin-top:18px;border-top:1px solid var(--ks-border-default);padding-top:12px;font-size:10px;color:var(--ks-text-secondary)}.adapter-details summary{cursor:pointer}.native-visual .native-blocks{padding:15px}.native-visual :deep(.block-section-card){border:0}.native-visual :deep(.leaf-block-card){min-height:74px;margin-bottom:12px}.native-block-item{position:relative}.native-child-toggle{position:absolute;right:10px;top:8px;z-index:2;font-size:9px;color:var(--ks-text-secondary);background:var(--ks-bg-surface);border-radius:3px;padding:2px 5px}</style>

<style scoped>.native-visual :deep(.leaf-block-card){min-height:60px;margin-bottom:10px}.native-inspector h3{margin-bottom:10px}.native-inspector textarea{min-height:130px}</style>
